CREATE OR REPLACE FUNCTION total_loans()
    RETURNS TRIGGER
    AS $$
    BEGIN
        UPDATE loan_summary
        SET total_loan_count = (SELECT COUNT(CASE WHEN status = 'A' THEN 1 END) FROM loan WHERE loan_summary.account_id = loan.account_id) WHERE account_id = NEW.account_id; RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

stage1_sql:
CREATE OR REPLACE FUNCTION update_loan_summary()
    RETURNS TRIGGER
    AS $$
    BEGIN
        -- Only update if status actually changed
        IF OLD.status IS DISTINCT FROM NEW.status THEN
            UPDATE loan_summary
            SET total_loan_count = (
                SELECT COUNT(*) 
                FROM loan 
                WHERE account_id = NEW.account_id AND status = 'A'
            )
            WHERE account_id = NEW.account_id;
        END IF;
        RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

CREATE TRIGGER tr_total_loans 
    AFTER UPDATE OF status 
    ON loan 
    FOR EACH ROW 
    EXECUTE PROCEDURE update_loan_summary();

