CREATE OR REPLACE FUNCTION what_quarter_is(date_in date, start_month int)
RETURNS int AS $$
DECLARE
    month_num int;
    offset int;
BEGIN
    month_num := EXTRACT(MONTH FROM date_in)::int;
    offset := (month_num - start_month + 12) % 12;
    RETURN (offset / 3) + 1;
END;
$$ LANGUAGE plpgsql;

