CREATE OR REPLACE FUNCTION what_quarter_is(date_in DATE, start_month INTEGER)
RETURNS INTEGER AS $$
BEGIN
    RETURN ((EXTRACT(MONTH FROM date_in) - start_month + 12) % 12) / 3 + 1;
END;
$$ LANGUAGE plpgsql;

-- Usage example:
SELECT trans_id, date, what_quarter_is(date, 4) AS quarter
FROM trans
WHERE date >= '1995-01-01' AND date <= '1995-12-31';

-- Alternative: Create a reusable function for configurable quarter calculation
CREATE OR REPLACE FUNCTION what_quarter_is(date_in DATE, start_month INTEGER)
RETURNS INTEGER AS $$
DECLARE
    month_num INTEGER;
    offset INTEGER;
BEGIN
    month_num := EXTRACT(MONTH FROM date_in)::INTEGER;
    -- Calculate offset from start month (0-11 range)
    offset := (month_num - start_month + 12) % 12;
    -- Determine quarter (1-4)
    RETURN (offset / 3) + 1;
END;
$$ LANGUAGE plpgsql;

-- Usage example with the function
SELECT 
    trans_id,
    account_id,
    date,
    what_quarter_is(date, 4) AS custom_quarter,
    EXTRACT(YEAR FROM date) AS year
FROM trans
ORDER BY date;

