CREATE OR REPLACE FUNCTION f_gap_fill_update(tbl text, id text, row_num text) 
RETURNS void 
LANGUAGE plpgsql 
AS $func$ 
DECLARE 
    tmp text[]; 
    col text; 
BEGIN 
    -- Get all nullable columns
    SELECT array_agg(column_name) 
    INTO tmp 
    FROM information_schema.columns 
    WHERE table_name = tbl 
    AND is_nullable = 'YES';

    -- Loop through each nullable column
    FOREACH col IN ARRAY tmp LOOP
        -- Update with forward fill using LAST_VALUE with IGNORE NULLS
        EXECUTE format(
            'UPDATE %I SET %I = (
                SELECT filled_value FROM (
                    SELECT %I, %I, 
                           LAST_VALUE(%I IGNORE NULLS) OVER (
                               PARTITION BY %I ORDER BY %I
                           ) as filled_value
                    FROM %I
                ) sub
                WHERE sub.%I = %I.%I
            )',
            tbl, col, col, row_num, col, id, row_num, tbl, row_num, tbl, row_num
        );
    END LOOP;
END;
$func$;

CREATE OR REPLACE FUNCTION f_gap_fill_update(tbl text, id text, row_num text) 
RETURNS void 
LANGUAGE plpgsql 
AS $func$ 
DECLARE 
    tmp text[]; 
    col text; 
BEGIN 
    -- Get all nullable columns from the specified table
    SELECT array_agg(column_name) 
    INTO tmp 
    FROM information_schema.columns 
    WHERE table_name = tbl 
    AND is_nullable = 'YES';

    -- Loop through each nullable column and apply forward fill
    FOREACH col IN ARRAY tmp LOOP
        -- Update the column with forward-filled values using LAST_VALUE with IGNORE NULLS
        EXECUTE format(
            'UPDATE %I SET %I = (
                SELECT filled_value FROM (
                    SELECT %I, %I, 
                           LAST_VALUE(%I IGNORE NULLS) OVER (
                               PARTITION BY %I ORDER BY %I
                           ) as filled_value
                    FROM %I
                ) sub
                WHERE sub.%I = %I.%I
            )',
            tbl, col, col, row_num, col, id, row_num, tbl, row_num, tbl, row_num
        );
    END LOOP;
END;
$func$;

