DECLARE 
    tmp text[]; 
    col text; 
BEGIN 
    SELECT ARRAY(SELECT column_name FROM information_schema.columns c WHERE table_name = tbl) INTO tmp; 
    FOREACH col IN ARRAY tmp LOOP 
        EXECUTE 'UPDATE ' || tbl || ' SET ' || col || ' = (SELECT ' || col || ' FROM ' || tbl || ' t2 WHERE t2.' || id || ' = ' || tbl || '.' || id || ' AND t2.' || row_num || ' <= ' || tbl || '.' || row_num || ' AND t2.' || col || ' IS NOT NULL ORDER BY t2.' || row_num || ' DESC LIMIT 1) WHERE ' || col || ' IS NULL'; 
    END LOOP; 
END $func$;

