CREATE OR REPLACE FUNCTION pg_try_advisory_lock_with_timeout(key bigint)
RETURNS boolean AS $$
DECLARE
    start_time timestamp;
    result boolean;
BEGIN
    start_time := clock_timestamp();

    -- Try to acquire the lock
    result := pg_try_advisory_xact_lock(key);

    -- If we got the lock, return true
    IF result THEN
        RETURN true;
    END IF;

    -- If we didn't get the lock, we could implement polling here
    -- But pg_try_advisory_xact_lock doesn't wait, so we return false immediately
    RETURN false;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pg_try_advisory_lock_with_timeout(key bigint)
RETURNS boolean AS $$
DECLARE
    start_time timestamp;
    elapsed interval;
BEGIN
    start_time := clock_timestamp();

    -- Loop until we get the lock or timeout
    LOOP
        -- Try to acquire the lock
        IF pg_try_advisory_xact_lock(key) THEN
            RETURN true;
        END IF;

        -- Check if we've exceeded the timeout (1 second)
        elapsed := clock_timestamp() - start_time;
        IF elapsed > interval '1 second' THEN
            RETURN false;
        END IF;

        -- Sleep briefly before retrying
        PERFORM pg_sleep(0.01);
    END LOOP;
END;
$$ LANGUAGE plpgsql;

