CREATE OR REPLACE FUNCTION pg_try_advisory_lock_with_timeout(key bigint)
RETURNS boolean AS $$
DECLARE
    result boolean;
BEGIN
    -- Set the lock timeout to 1 second for this transaction/block
    SET LOCAL lock_timeout = '1s';

    BEGIN
        -- Attempt to acquire the lock. 
        -- If it times out, PostgreSQL raises an exception (SQLSTATE 55P03)
        PERFORM pg_advisory_xact_lock(key);
        result := true;
    EXCEPTION
        WHEN lock_timeout THEN
            result := false;
        WHEN OTHERS THEN
            -- Re-raise other unexpected errors
            RAISE;
    END;

    -- Reset lock_timeout to default (infinite) for subsequent operations
    SET LOCAL lock_timeout = NULL;

    RETURN result;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pg_try_advisory_lock_with_timeout(key bigint)
RETURNS boolean AS $$
DECLARE
    result boolean;
BEGIN
    -- Set the lock timeout to 1 second for the current transaction
    SET LOCAL lock_timeout = '1s';

    BEGIN
        -- Attempt to acquire the advisory lock.
        -- If the lock cannot be acquired within 1 second, 
        -- PostgreSQL raises a 'lock_timeout' exception.
        PERFORM pg_advisory_xact_lock(key);
        result := true;
    EXCEPTION
        WHEN lock_timeout THEN
            -- If timeout occurs, return false
            result := false;
        WHEN OTHERS THEN
            -- Re-raise any other unexpected errors
            RAISE;
    END;

    -- Reset lock_timeout to default (infinite) to avoid side effects
    SET LOCAL lock_timeout = NULL;

    RETURN result;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pg_try_advisory_lock_with_timeout(key bigint, timeout_seconds integer DEFAULT 1)
RETURNS boolean AS $$
DECLARE
    start_time timestamp;
    current_time timestamp;
    elapsed_seconds integer;
BEGIN
    start_time := clock_timestamp();

    LOOP
        -- Try to acquire the lock without blocking
        IF pg_try_advisory_lock(key) THEN
            RETURN true;
        END IF;

        -- Check if we have exceeded the timeout
        current_time := clock_timestamp();
        elapsed_seconds := EXTRACT(EPOCH FROM (current_time - start_time))::integer;

        IF elapsed_seconds >= timeout_seconds THEN
            RETURN false;
        END IF;

        -- Wait a short interval before retrying (e.g., 100ms)
        PERFORM pg_sleep(0.1);
    END LOOP;
END;
$$ LANGUAGE plpgsql;

