CREATE OR REPLACE FUNCTION find_next_available_date(input_date date)
RETURNS date AS $$
DECLARE
    check_date date := input_date;
BEGIN
    LOOP
        IF NOT EXISTS (SELECT 1 FROM races WHERE date = check_date) THEN
            RETURN check_date;
        END IF;
        check_date := check_date + INTERVAL '1 day';
    END LOOP;
END;
$$ LANGUAGE plpgsql;

