-- The circular foreign key problem: account references disp AND disp references account
-- Solution: Remove the FK from account to disp. Keep only disp -> account FK.
-- The "at least one disp per account" requirement should be enforced via trigger, not FK.

-- Drop the problematic FK if it exists (it shouldn't in current schema)
ALTER TABLE account DROP COLUMN IF EXISTS disp_id;

-- The correct schema already exists:
-- - account table: account_id, district_id, frequency, date
-- - disp table: disp_id, client_id, account_id, type (with FK to account)
-- - card table: card_id, disp_id, type, issued (with FK to disp)

-- To enforce "each account must have at least one disp", create a trigger:
DROP TRIGGER IF EXISTS enforce_account_has_disp ON account;

CREATE OR REPLACE FUNCTION check_account_has_disp()
RETURNS TRIGGER AS $$
BEGIN
    -- Only check on DELETE of account
    IF TG_OP = 'DELETE' THEN
        IF EXISTS (SELECT 1 FROM disp WHERE account_id = OLD.account_id) THEN
            RAISE EXCEPTION 'Cannot delete account %: it has associated dispositions', OLD.account_id;
        END IF;
    END IF;
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER enforce_account_has_disp
    BEFORE DELETE ON account
    FOR EACH ROW
    EXECUTE FUNCTION check_account_has_disp();

