RETURNS TRIGGER AS $$
BEGIN
    -- Update stage1 in dependency table when match1 matches the updated match id
    UPDATE dependency 
    SET stage1 = NEW.stage 
    WHERE match1 = NEW.id;

    -- Update stage2 in dependency table when match2 matches the updated match id
    UPDATE dependency 
    SET stage2 = NEW.stage 
    WHERE match2 = NEW.id;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

