CREATE OR REPLACE FUNCTION calculate_loan_status()
RETURNS SETOF loan_last
AS $$
DECLARE
    temp_table_name text := 'temp_loan_status_' || pg_backend_pid();
BEGIN
    -- Create a temporary table dynamically
    EXECUTE format('CREATE TEMP TABLE %I (loan_id bigint, status text)', temp_table_name);

    -- Insert data from loan_first into the temporary table
    EXECUTE format('INSERT INTO %I SELECT loan_id, status FROM loan_first WHERE status = ''A''', temp_table_name);

    -- Insert data from the temporary table into loan_last
    EXECUTE format('INSERT INTO loan_last SELECT loan_id, status FROM %I', temp_table_name);

    -- Return the result set from loan_last
    RETURN QUERY SELECT * FROM loan_last;

    -- Clean up the temporary table (optional, as it's session-scoped)
    EXECUTE format('DROP TABLE IF EXISTS %I', temp_table_name);
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION calculate_loan_status()
    RETURNS SETOF loan_last
    AS $$
    BEGIN 
        INSERT INTO loan_last SELECT loan_id, status FROM loan_first WHERE status = 'A';
        RETURN QUERY SELECT * FROM loan_last;
    END;
    $$ LANGUAGE plpgsql;

