create or replace function setup_vector_store(table_name text) returns void language plpgsql as $$ 
begin 
    execute format('drop function if exists match_%I(int, jsonb)', table_name);
    execute format('create table %I ( 
        id bigint primary key generated always as identity, 
        description text, 
        metadata jsonb,
        embedding vector
    )', table_name);
    execute format('create function match_%I ( 
        query_embedding vector,
        match_count int default null, 
        filter jsonb default ''{}''::jsonb 
    ) returns table ( 
        id bigint, 
        description text, 
        metadata jsonb, 
        similarity float 
    ) language plpgsql as $$ 
    begin 
        return query 
        select id, description, metadata, embedding <=> query_embedding as similarity 
        from %I 
        where metadata @> filter 
        order by embedding <=> query_embedding 
        limit match_count; 
    end;$$;', table_name, table_name, table_name);
end; 
$$;

