CREATE OR REPLACE FUNCTION lcp_token_iterate(_state TEXT, _value TEXT) RETURNS TEXT AS $$
DECLARE
    state_tokens TEXT[];
    value_tokens TEXT[];
    i INTEGER;
    min_len INTEGER;
    result_tokens TEXT[];
BEGIN
    -- Handle NULLs
    IF _state IS NULL THEN
        RETURN _value;
    END IF;
    IF _value IS NULL THEN
        RETURN _state;
    END IF;

    -- Split by '#'
    state_tokens := string_to_array(_state, '#');
    value_tokens := string_to_array(_value, '#');

    -- Determine min length
    min_len := LEAST(array_length(state_tokens, 1), array_length(value_tokens, 1));

    -- Compare tokens
    FOR i IN 1..min_len LOOP
        IF state_tokens[i] = value_tokens[i] THEN
            result_tokens := array_append(result_tokens, state_tokens[i]);
        ELSE
            EXIT;
        END IF;
    END LOOP;

    -- Join back
    RETURN array_to_string(result_tokens, '#');
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION lcp_iterate(_state TEXT, _value TEXT) RETURNS TEXT AS $$
DECLARE
    state_tokens TEXT[];
    value_tokens TEXT[];
    i INTEGER;
    min_len INTEGER;
    result_tokens TEXT[];
BEGIN
    IF _state IS NULL THEN
        RETURN _value;
    END IF;
    IF _value IS NULL THEN
        RETURN _state;
    END IF;

    state_tokens := string_to_array(_state, '#');
    value_tokens := string_to_array(_value, '#');

    min_len := LEAST(array_length(state_tokens, 1), array_length(value_tokens, 1));

    FOR i IN 1..min_len LOOP
        IF state_tokens[i] = value_tokens[i] THEN
            result_tokens := array_append(result_tokens, state_tokens[i]);
        ELSE
            EXIT;
        END IF;
    END LOOP;

    RETURN array_to_string(result_tokens, '#');
END;
$$ LANGUAGE plpgsql;

