-- Step 1: Create a function to find the common prefix of two text arrays
CREATE OR REPLACE FUNCTION array_lcp_iterate(state text[], value text[]) RETURNS text[] AS $$
DECLARE
    i integer;
    min_len integer;
    result text[];
BEGIN
    -- Handle NULLs
    IF state IS NULL THEN
        RETURN value;
    END IF;
    IF value IS NULL THEN
        RETURN state;
    END IF;

    min_len := LEAST(array_length(state, 1), array_length(value, 1));

    -- If either is empty, return empty
    IF min_len = 0 THEN
        RETURN ARRAY[]::text[];
    END IF;

    -- Find the first index where they differ
    FOR i IN 1..min_len LOOP
        IF state[i] <> value[i] THEN
            -- Return the prefix up to i-1
            IF i = 1 THEN
                RETURN ARRAY[]::text[];
            ELSE
                RETURN state[1:i-1];
            END IF;
        END IF;
    END LOOP;

    -- If all compared elements match, return the shorter array
    RETURN state[1:min_len];
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Step 2: Create the aggregate
DO $$ 
BEGIN 
    CREATE AGGREGATE array_lcp_agg(text[]) (
        SFUNC = array_lcp_iterate,
        STYPE = text[],
        INITCOND = '{}'
    );
EXCEPTION 
    WHEN duplicate_object THEN NULL;
END $$;

