    idx AS rownum,
    (data->>'id_column')::BIGINT AS id_column,
    (data->>'decimal_column')::DECIMAL(28,8) AS decimal_column,
    (data->>'nvarchar_column')::VARCHAR(30) AS nvarchar_column
FROM jsonb_array_elements(
    '[
        {"id_column": 1234, "decimal_column": 12.34, "nvarchar_column": "asdf"},
        {"id_column": 5678, "decimal_column": 56.78, "nvarchar_column": "fdsa"}
    ]'::jsonb
) WITH ORDINALITY AS t(data, idx)
ORDER BY idx;

