stage2_sql:
-- 1. Create the General Categories Table
DROP TABLE IF EXISTS "EventCategories";

CREATE TABLE "EventCategories"( 
    "ID" INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, 
    "IsBusinessCategory" BOOLEAN NULL 
);

-- 2. Create the Business Categories Table
DROP TABLE IF EXISTS "BusinessCategories";

CREATE TABLE "BusinessCategories"( 
    "ID" INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, 
    "BusinessCategoryID" INT NOT NULL REFERENCES "EventCategories"("ID") 
);

-- 3. Create a function to enforce the conditional logic
CREATE OR REPLACE FUNCTION check_business_category_condition()
RETURNS TRIGGER AS $$
BEGIN
    -- Check if the referenced EventCategory exists and has IsBusinessCategory = true
    IF NOT EXISTS (
        SELECT 1 
        FROM "EventCategories" 
        WHERE "ID" = NEW."BusinessCategoryID" 
        AND "IsBusinessCategory" = true
    ) THEN
        RAISE EXCEPTION 'Cannot link to EventCategory %: IsBusinessCategory must be true.', NEW."BusinessCategoryID";
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 4. Create the trigger to enforce the rule on INSERT and UPDATE
DROP TRIGGER IF EXISTS enforce_business_category_flag ON "BusinessCategories";

CREATE TRIGGER enforce_business_category_flag
BEFORE INSERT OR UPDATE ON "BusinessCategories"
FOR EACH ROW
EXECUTE FUNCTION check_business_category_condition();

